'use strict';
const uid=p=>p+'-'+crypto.randomUUID().slice(0,12);
const mats=[['170101','Hormigón'],['170102','Ladrillo'],['170802','Yeso / placa'],['170201','Madera'],['150102','Film / envase'],['170203','Plástico de obra'],['170405','Hierro y acero'],['170202','Vidrio'],['150101','Cartón'],['170604','Aislamiento'],['170504','Tierra / piedras'],['150110*','Envase contaminado']];
let works=[{id:'PRAT',name:'El Prat · piloto',lat:41.325,lng:2.095},{id:'LLAR',name:'Llar de Mar · escenario',lat:40.025,lng:4.162},{id:'PIED',name:'Piedrahita · escenario',lat:40.457,lng:-5.319}];
let lastSavedJSON='';
let syncReady=false,syncEtag=null,syncTimer,syncBusy=false,syncDirty=false,syncConflict=false,channel='Obra',agentContext='normativa',captureStream,recorder,captureBlob=null,selectedMat='170802',selectedUnit=null,boardZoom=1,nodeConnect=null,visionBlob=null,visionURL=null,visionRegions=[];
function evolve(){state.v2??={operations:[],alerts:[],receipts:[],threads:[],connections:[],readings:[],tags:{},nodes:[],edges:[],assist:[],reviews:[],cameras:[],documents:[]};state.v2.works??=works;works=state.v2.works;for(const l of state.lots){l.work??='PRAT';l.lotId??='LOT-'+l.id;l.process??=l.status==='Cerrado'?'Tratado':l.status==='Recibido'?'Recibido':'En obra'}if(!state.v2.nodes.length){state.v2.nodes=[{id:'n-work',type:'Obra',ref:'PRAT',label:'El Prat · piloto',x:60,y:180},{id:'n-s1',type:'Unidad',ref:'SAC-001',label:'SAC-001 · yeso',x:400,y:70},{id:'n-s2',type:'Unidad',ref:'SAC-002',label:'SAC-002 · plástico',x:400,y:290},{id:'n-g',type:'Gestor',ref:'Planta demo',label:'Planta · recepción',x:750,y:180}];state.v2.edges=[{id:uid('EDGE'),from:'n-work',to:'n-s1',label:'genera'},{id:uid('EDGE'),from:'n-work',to:'n-s2',label:'genera'},{id:uid('EDGE'),from:'n-s1',to:'n-g',label:'destino por confirmar'}]}}
evolve();
const oldRender=render,oldUnit=unitDetail,oldPlanning=planning,oldControl=control;
nav.splice(5,0,['','mapa','Mapa de relaciones','link']);nav.splice(8,0,['GESTOR / PLANTA','planta','Centro del gestor','truck']);nav.push(['OBRAS','obras','Obras y zonas','layers']);nav.push(['INFRAESTRUCTURA','conectores','Lectores y conexiones','scan'],['','evidencias','Archivo de evidencias','file'],['','asistente','Asistente CUEVA','shield']);
const oldPersist=persist;
persist=function(){if(!syncReady)return;if(JSON.stringify(state)===lastSavedJSON)return;syncDirty=true;clearTimeout(syncTimer);$('#save-status').textContent='Guardando cambios…';syncTimer=setTimeout(saveRemote,600)};
async function api(path,options={}){const r=await CuevaPrototype.request(path,options);if(!r.ok){let d;try{d=await r.json()}catch{}throw Error(d?.error||'Servicio no disponible ('+r.status+')')}return r}
async function saveRemote(){if(syncBusy||!syncReady||syncConflict)return;syncBusy=true;syncDirty=false;try{const body=JSON.stringify(state);const r=await api('state',{method:'PUT',headers:{'Content-Type':'application/json','If-Match':syncEtag||'new'},body});syncEtag=r.headers.get('ETag');lastSavedJSON=body;$('#save-status').textContent='Guardado en este navegador · '+new Date().toLocaleTimeString('es-ES')}catch(e){syncDirty=true;if(e.message.includes('conflicto'))syncConflict=true;$('#save-status').textContent='Sin guardar: '+e.message+' · exporta una copia';toast(e.message)}finally{syncBusy=false;if(syncDirty&&!syncConflict)setTimeout(saveRemote,10000)}}
async function initRemote(){try{const r=await api('state');const data=await r.json();syncEtag=r.headers.get('ETag');if(data){state=data;evolve()}else{try{const legacy=JSON.parse(localStorage.getItem('cueva-wm-v1'));if(legacy?.lots&&legacy?.tasks){state=legacy;evolve()}}catch{}}if(data)lastSavedJSON=JSON.stringify(state);syncReady=true;render();$('#save-status').textContent='Demo autónoma · datos en este navegador';if(!data)persist()}catch(e){$('#main').insertAdjacentHTML('afterbegin','<div class="notice warn">El navegador no ha permitido abrir el almacenamiento local. Puedes consultar la base; las modificaciones quedan temporalmente en memoria. <button data-v2="retry">Reintentar conexión</button><button data-action="export-json">Exportar copia</button></div>');$('#save-status').textContent='Sin conexión · cambios no persistentes'}}
window.addEventListener('beforeunload',e=>{if(syncDirty||syncBusy){e.preventDefault();e.returnValue=''}});
function vbtn(t,a,cls='',extra=''){return `<button type="button" class="${cls}" data-v2="${esc(a)}" ${extra}>${t}</button>`}
function optsLots(id){return state.lots.map(l=>`<option value="${esc(l.id)}" ${l.id===id?'selected':''}>${esc(l.id)} · ${esc(ler(l.code).name)}</option>`).join('')}
function field(label,input){return `<div class="field"><label>${label}</label>${input}</div>`}
function alertList(unit){return state.v2.alerts.filter(a=>!unit||a.unit===unit).map(a=>`<article class="alert-item ${a.status==='Resuelta'?'resolved':''}"><div class="between"><b>${esc(a.title)}</b>${badge(a.status)}</div><p>${esc(a.note)}</p><small>${esc(a.unit)} · ${new Date(a.time).toLocaleString('es-ES')}</small>${a.status!=='Resuelta'?vbtn('Resolver con evidencia','resolve:'+a.id,'ghost'):''}</article>`).join('')||'<p class="muted">Sin incidencias en este ámbito.</p>'}
function raise(unit,title,note){const a={id:uid('INC'),unit,title,note,time:new Date().toISOString(),status:'Abierta'};state.v2.alerts.unshift(a);state.tasks.unshift({id:uid('T'),unit,title,owner:'Waste manager',due:new Date().toISOString().slice(0,10),stage:'Bloqueado',priority:'Alta',alertId:a.id,checklist:[]});return a}
render=function(){evolve();const extra={obras:worksView,mapa:networkBoard,planta:plant,conectores:connectorView,evidencias:evidenceView,asistente:assistantView};if(extra[route]){const target=route;route='control';oldRender();route=target;$('#main').innerHTML=extra[target]();$$('.navlink').forEach(a=>a.classList.toggle('active',a.hash==='#'+target));document.title=nav.find(n=>n[1]===target)[2]+' · CUEVA'}else oldRender();$('.version').textContent='02';if(!$('#assist-launch'))document.body.insertAdjacentHTML('beforeend',vbtn('✧ Asistente CUEVA','agent','agent-launch','id="assist-launch"'));if(route==='planificacion')enhanceTasks();if(['normativa','formacion','materiales','objetivos','estudio'].includes(route))$('#main').insertAdjacentHTML('afterbegin',`<div class="agent-strip"><span>✧ CUEVA · asistencia contextual</span>${vbtn('Consultar sobre esta sección','agent','ghost')}</div>`);if(route==='unidades')$('#main .actions')?.insertAdjacentHTML('beforeend',vbtn('Vertido / clasificación','deposit','primary'));};
control=function(){return `<div class="operation-bar"><div><span class="eyebrow">CUEVA / OPERACIONES CONECTADAS</span><h2>De la obra a la planta, con evidencia.</h2></div>${vbtn('Registrar vertido','deposit','primary')}${vbtn('Centro del gestor','nav:planta')}${vbtn('Mapa de relaciones','nav:mapa')}</div><div class="mini-stats"><span><b>${state.v2.operations.length}</b> operaciones registradas</span><span><b>${state.v2.alerts.filter(a=>a.status!=='Resuelta').length}</b> incidencias abiertas</span><span><b>${state.v2.readings.length}</b> lecturas recibidas</span><span><b>${state.v2.reviews.length}</b> revisiones visuales</span></div>`+oldControl().replace('Viernes, 11 de septiembre de 2026','Operación y seguimiento').replace('Masa conciliada','Balance de registros')};
unitDetail=function(id){oldUnit(id);const l=state.lots.find(l=>l.id===id);if(!l)return;$('#modal-content').insertAdjacentHTML('afterbegin',`<div class="unit-operate">${vbtn('＋ Vertido / clasificación manual','deposit:'+id,'primary')}${vbtn('Recogida y recepción','handoff:'+id)}${vbtn('Conversación','chat:'+id)}</div>`);$('#modal-content').insertAdjacentHTML('beforeend',`<h3 class="spaced">Operaciones de contenido</h3>${state.v2.operations.filter(o=>o.unit===id).map(o=>`<div class="source"><b>${esc(o.type)} · ${esc(ler(o.code).name)}</b><p>${o.amount} ${esc(o.measure)} · ${esc(o.condition)} · ${esc(o.status)}</p>${o.media?`<a href="${esc(o.media.url)}" target="_blank" rel="noopener">Abrir evidencia ↗</a>`:''}</div>`).join('')||'<p class="muted">Sin nuevas operaciones.</p>'}<h3 class="spaced">Incidencias</h3>${alertList(id)}`)};
function matCards(){return `<div class="material-picker">${mats.map(([c,n],i)=>`<button type="button" class="material-tile ${selectedMat===c?'selected':''}" data-v2="mat:${c}"><span class="material-image" style="background-position:${(i%4)*100/3}% ${Math.floor(i/4)*50}%"></span><b>${n}</b><small>${code(c)} ${c.endsWith('*')?'· peligroso':''}</small></button>`).join('')}</div>`}
function deposit(id){selectedUnit=id||state.lots.find(l=>l.status==='Acopio')?.id||state.lots[0].id;selectedMat=state.lots.find(l=>l.id===selectedUnit).code;captureBlob=null;modal('Registro de operación · obra',`<form id="v2-deposit"><div class="detailgrid">${field('Saca / contenedor',`<select name="unit" id="deposit-unit">${optsLots(selectedUnit)}</select>`)}${field('Operación','<select name="type"><option>Vertido manual</option><option>Clasificación manual</option><option>Retirada manual de contenido</option></select>')}</div><h3 class="spaced">Toca el residuo que vas a registrar</h3><div id="mat-picker">${matCards()}</div><div class="detailgrid">${field('LER seleccionado · confirmar origen',`<select name="code" id="deposit-code">${LER.map(l=>`<option value="${l.code}" ${l.code===selectedMat?'selected':''}>${code(l.code)} · ${l.name}</option>`).join('')}</select>`)}${field('Estado del residuo','<select name="condition"><option>Limpio y separado</option><option>Húmedo</option><option>Con impropios</option><option>Composición desconocida</option><option>Sospecha de contaminación</option></select>')}${field('Cantidad','<input name="amount" type="number" min="0.01" step="0.01" required>')}${field('Unidad / base de medición','<select name="measure"><option>kg estimados</option><option>kg pesados</option><option>unidades</option><option>m³ estimados</option></select>')}${field('Autor / operario','<input name="actor" value="Waste manager" required maxlength="80">')}${field('Observaciones','<input name="note" maxlength="500" placeholder="Origen, acabado, elementos adheridos…">')}</div><div id="compatibility"></div><div class="capture-area"><div><h3>Evidencia de la operación</h3><p class="small muted">Foto o vídeo en directo, o archivo existente. La clasificación material queda pendiente de revisión.</p><input type="file" id="capture-file" accept="image/jpeg,image/png,image/webp,video/webm,video/mp4" capture="environment"><div class="actions spaced">${vbtn('Abrir cámara','camera')}${vbtn('Tomar foto','snapshot')}${vbtn('Grabar / detener vídeo','record')}</div></div><div><video id="capture-video" playsinline muted autoplay></video><img id="capture-photo" alt="Evidencia capturada" hidden><small id="capture-status">Máximo 20 MB · vídeo hasta 20 segundos</small></div></div><div class="notice">Si la imagen no permite identificar el material, queda como soporte documental. Una coincidencia visual no valida por sí sola el código LER.</div><label class="checkline"><input type="checkbox" name="already"> Ya se ha producido la operación (registrar incidencia si es incompatible)</label><p class="formerror" id="v2-error"></p><div class="actions">${vbtn('Consultar compatibilidad','agent')}<button class="primary">Guardar operación y evidencia</button></div></form>`);compatibility()}
function compatibility(){const l=state.lots.find(l=>l.id===$('#deposit-unit')?.value);if(!l)return;selectedMat=$('#deposit-code').value;const bad=l.code!==selectedMat;$('#compatibility').innerHTML=`<div class="notice ${bad?'warn':''}"><b>${bad?'Atención: material distinto al asignado a esta unidad':'Coincidencia con la fracción declarada'}</b><p>Saca: ${code(l.code)} · residuo: ${code(selectedMat)}. ${bad?'No realizar el vertido. Busca una unidad compatible; si ya ocurrió se registrará una incidencia.':'Comprobar impropios, origen y peligrosidad antes del vertido.'}</p></div>`}
async function openCamera(){try{stopCapture();captureStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});$('#capture-video').srcObject=captureStream;$('#capture-video').hidden=false;$('#capture-status').textContent='Cámara activa · captura solo al pulsar'}catch{toast('No se pudo abrir la cámara. Revisa el permiso o adjunta un archivo.')}}
function stopCapture(){if(recorder?.state==='recording')recorder.stop();captureStream?.getTracks().forEach(t=>t.stop());captureStream=null}
async function snapshot(){const v=$('#capture-video');if(!v?.videoWidth)return toast('Abre la cámara primero.');const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);captureBlob=await new Promise(r=>c.toBlob(r,'image/jpeg',.85));$('#capture-photo').src=URL.createObjectURL(captureBlob);$('#capture-photo').hidden=false;$('#capture-status').textContent='Fotografía capturada · pendiente de guardar'}
function recordVideo(){if(recorder?.state==='recording'){recorder.stop();return}if(!captureStream||!window.MediaRecorder)return toast('Abre la cámara o adjunta un vídeo compatible.');const chunks=[];recorder=new MediaRecorder(captureStream);recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{captureBlob=new Blob(chunks,{type:recorder.mimeType});if($('#capture-status'))$('#capture-status').textContent='Vídeo capturado · pendiente de guardar'};recorder.start();$('#capture-status').textContent='Grabando · máximo 20 segundos';setTimeout(()=>{if(recorder?.state==='recording')recorder.stop()},20000)}
async function uploadEvidence(blob){if(!blob)throw Error('Adjunta una foto o graba una evidencia.');if(blob.size>20*1024*1024)throw Error('La evidencia supera 20 MB.');return (await api('media',{method:'POST',headers:{'Content-Type':blob.type},body:blob})).json()}
function networkBoard(){return page('Mapa de relaciones','Arrastra nodos, enlaza dos elementos y abre su expediente.',vbtn('＋ Nodo','node-new','primary')+vbtn('−','zoom-out')+vbtn('+','zoom-in')+vbtn('Exportar mapa','map-export'))+`<div class="board-legend"><span>Obras</span><span>Recipientes y lotes</span><span>Gestores</span><span>Tareas</span><small>Las conexiones representan relaciones declaradas.</small></div><div class="network-scroll"><div class="network-world" style="transform:scale(${boardZoom});transform-origin:0 0"><svg class="edge-layer" width="1400" height="850">${state.v2.edges.map(e=>{const a=state.v2.nodes.find(n=>n.id===e.from),b=state.v2.nodes.find(n=>n.id===e.to);if(!a||!b)return'';return `<g><path d="M${a.x+210},${a.y+60} C${a.x+310},${a.y+60} ${b.x-100},${b.y+60} ${b.x},${b.y+60}"/><text x="${(a.x+b.x+210)/2}" y="${(a.y+b.y+120)/2-10}">${esc(e.label)}</text></g>`}).join('')}</svg>${state.v2.nodes.map(n=>`<article class="graph-node ${n.type==='Obra'?'work-node':n.type==='Gestor'?'manager-node':''}" style="left:${n.x}px;top:${n.y}px" data-node="${n.id}"><header class="node-grip">${ico(n.type==='Unidad'?'box':n.type==='Obra'?'layers':'link')} ${esc(n.type)}</header><b>${esc(n.label)}</b><small>${esc(n.ref)}</small><div class="actions">${vbtn('Abrir','node-open:'+n.id,'ghost')}${vbtn(nodeConnect===n.id?'Origen ✓':'Enlazar','node-link:'+n.id,'ghost')}${vbtn('Editar','node-edit:'+n.id,'ghost')}</div></article>`).join('')}</div></div><section class="panel pad spaced"><h3>Conexiones</h3>${state.v2.edges.map(e=>`<div class="between source"><span>${esc(state.v2.nodes.find(n=>n.id===e.from)?.label)} → <b>${esc(e.label)}</b> → ${esc(state.v2.nodes.find(n=>n.id===e.to)?.label)}</span>${vbtn('Eliminar','edge-delete:'+e.id,'ghost')}</div>`).join('')}</section>`}
function nodeForm(id){const n=state.v2.nodes.find(n=>n.id===id);modal(n?'Editar nodo':'Añadir nodo',`<form id="v2-node" data-id="${n?.id||''}">${field('Tipo','<select name="type">'+['Obra','Unidad','Gestor','Tarea','Nota'].map(t=>`<option ${n?.type===t?'selected':''}>${t}</option>`).join('')+'</select>')}${field('Referencia (ID de unidad, obra o tarea)',`<input name="ref" list="node-refs" value="${esc(n?.ref||'')}" required><datalist id="node-refs">${[...state.lots.map(l=>l.id),...works.map(w=>w.id),...state.tasks.map(t=>t.id)].map(x=>`<option>${esc(x)}</option>`).join('')}</datalist>`)}${field('Nombre',`<input name="label" value="${esc(n?.label||'')}" required maxlength="70">`)}<div class="detailgrid">${field('Posición horizontal',`<input name="x" type="number" min="0" max="1150" value="${n?.x??100}">`)}${field('Posición vertical',`<input name="y" type="number" min="0" max="650" value="${n?.y??100}">`)}</div><button class="primary spaced">Guardar nodo</button>${n?vbtn('Eliminar nodo','node-delete:'+n.id,'danger'):''}</form>`)}
planning=function(){return `<div class="agent-strip"><span>ORGANIZACIÓN · tablero propio CUEVA</span>${vbtn('Abrir mapa de nodos','nav:mapa')}${vbtn('Buscar tareas','task-search')}</div>`+oldPlanning().replace(/Trello/g,'CUEVA')};
function enhanceTasks(){$$('[draggable="true"]').forEach(el=>{const id=el.dataset.task||el.dataset.id||el.getAttribute('data-drag');const t=state.tasks.find(t=>t.id===id)||state.tasks.find(t=>el.textContent.includes(t.title));if(t&&!el.querySelector('[data-v2]'))el.insertAdjacentHTML('beforeend',vbtn('Detalle · checklist · comentarios','task:'+t.id,'task-more'))})}
function taskDetail(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;modal('Tarea · '+t.title,`<form id="v2-task" data-id="${esc(id)}">${field('Título',`<input name="title" value="${esc(t.title)}" required maxlength="160">`)}<div class="detailgrid">${field('Responsable',`<input name="owner" value="${esc(t.owner)}" required>`)}${field('Fecha límite',`<input name="due" type="date" value="${esc(t.due)}" required>`)}${field('Prioridad','<select name="priority">'+['Alta','Media','Baja'].map(x=>`<option ${t.priority===x?'selected':''}>${x}</option>`).join('')+'</select>')}${field('Estado','<select name="stage">'+['Por hacer','En curso','Bloqueado','Hecho'].map(x=>`<option ${t.stage===x?'selected':''}>${x}</option>`).join('')+'</select>')}</div>${field('Descripción',`<textarea name="description">${esc(t.description||'')}</textarea>`)}${field('Etiquetas (separadas por coma)',`<input name="tags" value="${esc(t.tags||'')}">`)}${field('Checklist · una línea por punto · [x] para completado',`<textarea name="checklist">${esc((t.checklist||[]).map(c=>(c.done?'[x] ':'[ ] ')+c.text).join('\n'))}</textarea>`)}${field('Nuevo comentario','<textarea name="comment" maxlength="800"></textarea>')}<div class="source">${(t.comments||[]).map(c=>`<p>${esc(c.text)} <small>${esc(c.time)}</small></p>`).join('')}</div><button class="primary">Guardar cambios</button></form>`)}
function plant(){const f=filters.plantWork||'',s=filters.plantStatus||'',items=state.lots.filter(l=>(!f||l.work===f)&&(!s||l.process===s));const received=items.filter(l=>['Recibido','En clasificación','Tratado'].includes(l.process));return page('Centro del gestor','Recogida, entrada en planta, pesaje, clasificación y tratamiento.',vbtn('Registrar movimiento','handoff','primary')+vbtn('Exportar entradas','plant-export'),'GESTOR / VISTA OPERATIVA · PERFIL DE DEMOSTRACIÓN')+`<div class="toolbar"><select id="plant-work"><option value="">Todas las obras</option>${works.map(w=>`<option value="${w.id}" ${f===w.id?'selected':''}>${w.name}</option>`).join('')}</select><select id="plant-status"><option value="">Todos los estados</option>${['En obra','Recogido','Recibido','En clasificación','Tratado','Rechazado'].map(x=>`<option ${s===x?'selected':''}>${x}</option>`).join('')}</select><span class="badge">Acceso privado del propietario · perfiles aún sin cuentas separadas</span></div><div class="kpis">${metric('Unidades visibles',items.length,'Filtradas por obra y estado','box')}${metric('Recibidas',received.length,'Incluye clasificación y tratamiento','truck')}${metric('Masa recibida',kg(received.reduce((a,l)=>a+l.kg,0)),'Pesaje o dato de ejemplo identificado','layers')}${metric('Por clasificar',items.filter(l=>l.process==='Recibido').length,'Revisar aceptación y composición','alert')}</div><div class="grid2"><section class="panel pad"><h2>GIS · origen de activos</h2><div class="geo-map"><svg viewBox="0 0 620 290" role="img" aria-label="Mapa de coordenadas de obras; marcadores de ejemplo">${Array.from({length:7},(_,i)=>`<path d="M${40+i*80} 20V265M30 ${25+i*38}H600"/>`).join('')}${works.map(w=>{const minX=Math.min(...works.map(z=>z.lng))-1,maxX=Math.max(...works.map(z=>z.lng))+1,minY=Math.min(...works.map(z=>z.lat))-.5,maxY=Math.max(...works.map(z=>z.lat))+.5;const x=45+(w.lng-minX)/(maxX-minX)*490,y=245-(w.lat-minY)/(maxY-minY)*200;return `<g><circle cx="${x}" cy="${y}" r="11"/><text x="${Math.min(x+18,435)}" y="${y-10}">${esc(w.name.split(' ·')[0])}</text><text x="${Math.min(x+18,435)}" y="${y+10}">${state.lots.filter(l=>l.work===w.id&&['Recibido','En clasificación','Tratado'].includes(l.process)).length} recibidos</text></g>`}).join('')}</svg><span class="map-note">WGS84 · coordenadas de referencia · no localización en directo</span></div>${works.map(w=>`<div class="between small source"><b>${w.name}</b><a href="https://www.openstreetmap.org/?mlat=${w.lat}&mlon=${w.lng}#map=16/${w.lat}/${w.lng}" target="_blank" rel="noopener">Abrir cartografía ↗</a></div>`).join('')}</section><section class="panel pad"><h2>Composición recibida</h2>${[...new Set(received.map(l=>l.code))].map(c=>{const n=received.filter(l=>l.code===c).reduce((a,l)=>a+l.kg,0),total=received.reduce((a,l)=>a+l.kg,0);return `<div class="spaced between"><span>${esc(ler(c).name)}</span><b>${kg(n)}</b></div><div class="progress"><span style="width:${total?n/total*100:0}%"></span></div>`}).join('')||'<p>Sin unidades recibidas para el filtro.</p>'}</section></div><section class="panel"><div class="tablewrap"><table><thead><tr><th>Activo / lote</th><th>Obra / cliente</th><th>Material y masa</th><th>Proceso</th><th>Acción</th></tr></thead><tbody>${items.map(l=>`<tr><td><button data-unit="${l.id}">${l.id}</button><small>${l.lotId}</small></td><td>${esc(works.find(w=>w.id===l.work)?.name||l.work)}<small>${esc(l.manager||'Destino pendiente')}</small></td><td>${cb(l.code)}<small>${kg(l.kg)} · ${esc(l.method)}</small></td><td>${badge(l.process)}</td><td>${vbtn('Movimiento','handoff:'+l.id,'ghost')}</td></tr>`).join('')}</tbody></table></div></section>`}
function handoff(id){const l=state.lots.find(l=>l.id===id)||state.lots[0];modal('Cadena de custodia · gestor',`<form id="v2-handoff"><div class="detailgrid">${field('Unidad',`<select name="unit">${optsLots(l.id)}</select>`)}${field('Movimiento','<select name="step"><option>Recogida</option><option>Recepción</option><option>Clasificación</option><option>Rechazo</option></select>')}${field('Gestor / planta',`<input name="manager" value="${esc(l.manager||'')}" required maxlength="120">`)}${field('Responsable del registro','<input name="actor" value="Gestor · revisión" required>')}${field('Peso bruto (kg) · opcional en recogida','<input name="gross" type="number" min="0" step="0.01">')}${field('Tara (kg)','<input name="tare" type="number" min="0" step="0.01" value="0">')}${field('Ticket de báscula / referencia','<input name="ticket" maxlength="100">')}${field('Documento de identificación (DI)',`<input name="di" value="${esc(l.di||'')}" maxlength="120">`)}${field('Lectura / identificación en recepción',`<input name="scan" value="${esc(l.id)}" required>`)}${field('Zona de planta','<input name="zone" placeholder="Báscula 1 / playa de clasificación">')}</div>${field('Observación / diferencias / motivo de rechazo','<textarea name="note" required maxlength="1000"></textarea>')}<label class="checkline"><input type="checkbox" name="accepted" required> He comprobado la aceptación, el destino y la documentación aplicable</label><div class="notice">Recepción exige peso neto documentado en obra o en planta. Clasificar no acredita el reciclado final; el cierre se realiza en el expediente.</div><p id="v2-error" class="formerror"></p><button class="primary">Registrar movimiento</button></form>`)}
team=function(){const messages=state.v2.threads.filter(m=>m.channel===channel);return page('Conector de obra','Conversaciones vinculadas a la unidad, responsables y acciones.',vbtn('Asistente de coordinación','agent'),'EQUIPO / HISTÓRICO COMPARTIDO EN EL ESPACIO PRIVADO')+`<div class="chat-workspace"><aside class="chat-channels"><h3>Canales</h3>${['Obra','Logística','Calidad','Gestor','Formación'].map(c=>vbtn('# '+c,'channel:'+c,channel===c?'active':'')).join('')}<h3 class="spaced">Perfiles</h3><p>Waste manager<br>Encargado<br>Operario<br>Gestor</p><small>Perfiles de trabajo simulados. No representan usuarios autenticados distintos.</small></aside><section class="panel chat-main"><div class="panelhead"><h2># ${channel}</h2><span class="badge">${messages.length} mensajes</span></div><div class="thread-list">${messages.map(m=>`<article class="thread"><div class="avatar">${esc(m.actor.slice(0,2).toUpperCase())}</div><div class="grow"><div class="between"><b>${esc(m.actor)}</b><small>${new Date(m.time).toLocaleString('es-ES')}</small></div><p>${esc(m.text)}</p><div class="actions">${vbtn(m.unit,'unit:'+m.unit,'ghost')}${vbtn(m.ack?'Confirmado ✓':'Confirmar lectura','ack:'+m.id,'ghost')}${vbtn('Convertir en tarea','message-task:'+m.id,'ghost')}</div>${m.media?`<a href="${esc(m.media.url)}" target="_blank" rel="noopener">Ver adjunto ↗</a>`:''}</div></article>`).join('')||'<div class="empty">Abre una conversación sobre la siguiente operación.</div>'}</div><form id="v2-chat" class="pad"><div class="detailgrid">${field('Autor','<select name="actor"><option>Waste manager</option><option>Encargado</option><option>Operario</option><option>Gestor</option></select>')}${field('Unidad',`<select name="unit">${optsLots(selectedUnit)}</select>`)}</div>${field('Mensaje · menciona a un rol con @','<textarea name="text" required maxlength="2000" placeholder="@Encargado: revisar los impropios de SAC-001 antes de la retirada…"></textarea>')}${field('Foto / vídeo opcional','<input name="attachment" type="file" accept="image/jpeg,image/png,image/webp,video/webm,video/mp4">')}<p id="v2-error" class="formerror"></p><button class="primary">Registrar mensaje</button></form></section><aside class="panel pad"><h3>Incidencias de obra</h3>${alertList()}<h3 class="spaced">Histórico anterior</h3>${state.messages.map(m=>`<div class="source"><b>${esc(m.role)}</b><p>${esc(m.text)}</p><small>${esc(m.time)} · ${esc(m.unit)}</small></div>`).join('')}</aside></div>`};
const knowledge=[{keys:['yeso','placa','pladur'],text:'Separa el yeso de hormigón y cerámica. Comprueba si hay contaminación: 17 08 02 es la propuesta para materiales de construcción a base de yeso distintos de los especificados en 17 08 01*. Protege el acopio de humedad y confirma condiciones de aceptación del destino.',source:'https://www.boe.es/doue/2014/370/L00044-00086.pdf',title:'Lista Europea de Residuos'}, {keys:['plastico','film','envase'],text:'Distingue plástico procedente de construcción (17 02 03) y envase de plástico (15 01 02). Si el envase contiene restos peligrosos o está contaminado por ellos, revisa 15 01 10*. La apariencia o una fotografía no resuelven la peligrosidad.',source:'https://www.boe.es/doue/2014/370/L00044-00086.pdf',title:'LER · origen y composición'}, {keys:['norma','ley','separ','demolic'],text:'El art. 30 de la Ley 7/2022 establece la clasificación de RCD no peligrosos en madera, fracciones minerales, metales, vidrio, plástico y yeso. La demolición selectiva es obligatoria desde el 1 de enero de 2024. Revisa además el plan de gestión y las condiciones territoriales aplicables.',source:'https://www.boe.es/buscar/act.php?id=BOE-A-2022-5809',title:'Ley 7/2022 · art. 30'}, {keys:['gestor','recog','recep','traslado','document'],text:'Vincula la unidad con el lote, destino aceptado, documento de identificación y pesaje. Registra diferencias de masa y rechazo. La recepción no equivale a tratamiento final y R12/R13 no acreditan por sí solos reciclado.',source:'https://www.boe.es/buscar/act.php?id=BOE-A-2020-6422',title:'RD 553/2020 · traslados'}, {keys:['peligro','amianto','contamina'],text:'Detén la operación ordinaria y pide caracterización técnica. Una foto no descarta amianto, contaminantes ni peligrosidad. Conserva evidencia sin manipular el residuo para obtenerla. La clasificación exige conocer origen, composición y propiedades relevantes.',source:'https://www.boe.es/doue/2014/370/L00044-00086.pdf',title:'LER · entradas peligrosas'}, {keys:['objetivo','recicla','70','90'],text:'Distingue el objetivo interno del requisito aplicable y la tasa medida. No cuentes almacenamiento R13, tratamiento intermedio R12 o valorización energética R1 como reciclado material. El denominador y las exclusiones deben quedar visibles.',source:'https://www.boe.es/buscar/act.php?id=BOE-A-2022-5809',title:'Ley 7/2022 · objetivos'}];
function agentReply(q){const query=fold(q);const hit=knowledge.filter(k=>k.keys.some(x=>query.includes(x)));const l=state.lots.find(l=>query.includes(fold(l.id)));const a=state.v2.alerts.filter(a=>a.status!=='Resuelta'&&(!l||a.unit===l.id));return {text:(l?`${l.id}: ${ler(l.code).name}, ${kg(l.kg)}, estado ${l.status}. `:'')+(hit.length?hit.map(k=>k.text).join('\n\n'):'Puedo revisar compatibilidad declarada, LER, recepción, objetivos y tareas. Indica el ID de unidad y qué material u operación quieres comprobar. Para una interpretación no cubierta, registra una consulta técnica; no completaré una respuesta normativa por suposición.')+(a.length?'\n\nIncidencias abiertas relacionadas: '+a.map(a=>a.title).join('; '):''),sources:hit.map(k=>({url:k.source,title:k.title})),mode:'Motor de reglas y fuentes · sin modelo generativo'} }
function assistantView(){return page('Asistente CUEVA','Consulta normativa, compatibilidad y siguientes pasos con el contexto de los registros.',vbtn('Revisar incongruencias','audit','primary'))+`<section class="panel pad"><div class="notice">Motor contextual de reglas y fuentes documentadas. Conector a agente externo preparado; sin un proveedor configurado no se utiliza un LLM. Las respuestas no son una certificación.</div>${agentContent()}</section>`}
function agentContent(){return `<div class="prompt-chips">${['¿Puedo mezclar yeso con hormigón?','¿Qué documentación necesita la recepción?','Revisa las incidencias de SAC-001','¿Cómo se calcula el reciclado?'].map(q=>vbtn(q,'ask:'+q,'ghost')).join('')}</div><div id="agent-messages">${state.v2.assist.slice(-12).map(m=>`<article class="agent-answer ${m.role}"><b>${m.role==='user'?'Consulta':'CUEVA · '+esc(m.mode||'asistencia')}</b><p>${esc(m.text).replace(/\n/g,'<br>')}</p>${(m.sources||[]).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a>`).join(' · ')}</article>`).join('')}</div><form id="v2-agent"><input name="question" required maxlength="1500" placeholder="Material, unidad, duda o siguiente paso…" aria-label="Consulta al asistente"><button class="primary">Consultar</button></form>`}
function agentOpen(){agentContext=route;modal('✧ Asistente CUEVA · '+(nav.find(n=>n[1]===route)?.[2]||route),agentContent())}
async function ask(q){state.v2.assist.push({role:'user',text:q,time:new Date().toISOString()});let reply=agentReply(q);try{const r=await api('agent',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,context:agentContext,summary:state.lots.map(l=>({id:l.id,code:l.code,status:l.status})),sources:knowledge})});const a=await r.json();if(a.configured&&typeof a.text==='string')reply={...a,mode:'Agente externo · revisar fuentes'};}catch{}state.v2.assist.push({role:'assistant',...reply,time:new Date().toISOString()});persist();if(route==='asistente'&&!$('#modal').open)render();else $('#modal-content').innerHTML=agentContent()}
function connectorView(){return page('Lectores y conexiones','Identifica unidades, conserva eventos originales y prepara la conexión con vuestro manager.',vbtn('Contrato API','contract')+vbtn('Nueva conexión','connection-new','primary'))+`<div class="grid3">${[['RFID / NFC / QR','Lectura → etiqueta → recipiente → lote','scan'],['Báscula','Ticket → bruto / tara → neto','layers'],['Cámara / visión','Captura → análisis → revisión','camera']].map(([t,s,i])=>`<section class="panel pad">${ico(i)}<h2>${t}</h2><p>${s}</p><span class="badge amber">${t.startsWith('RFID')?state.v2.readings.length+' lecturas registradas':'Sin equipo externo configurado'}</span></section>`).join('')}</div><div class="grid2"><section class="panel pad"><h2>Vincular etiqueta a recipiente</h2><form id="v2-tag">${field('EPC / UID / identificador','<input name="epc" required maxlength="128" placeholder="3034… o NFC-…">')}${field('Unidad',`<select name="unit">${optsLots()}</select>`)}<button class="primary spaced">Vincular etiqueta</button></form>${Object.entries(state.v2.tags).map(([e,u])=>`<div class="between source"><code>${esc(e)}</code><b>${esc(u)}</b></div>`).join('')}</section><section class="panel pad"><h2>Ingesta y validación de lecturas</h2><p class="small muted">Pega un evento real exportado o utiliza el ejemplo de prueba. El ID de evento evita duplicados.</p><form id="v2-reading"><textarea name="payload" rows="9" aria-label="Evento JSON" required>${esc(JSON.stringify({eventId:uid('test'),readerId:'URA4-DEMO',epc:'TAG-DEMO-001',observedAt:new Date().toISOString(),siteId:'PRAT',zoneId:'Salida',rssiDbm:-49},null,2))}</textarea><p id="v2-error" class="formerror"></p><button class="primary">Validar y registrar evento</button></form></section></div><section class="panel pad"><h2>Conexiones configuradas</h2>${state.v2.connections.map(c=>`<div class="source between"><div><b>${esc(c.name)}</b><p>${esc(c.kind)} · ${esc(c.url)}</p><small>Configuración guardada · no acredita comunicación</small></div>${vbtn('Editar','connection-edit:'+c.id)}</div>`).join('')||'<p>Configura endpoints y sesiones. Los secretos se gestionan en servidor.</p>'}</section><section class="panel"><div class="panelhead"><h2>Histórico de lecturas</h2>${vbtn('Actualizar desde pasarela','pull-readings')}</div><div class="tablewrap"><table><thead><tr><th>Evento / lector</th><th>Etiqueta / unidad</th><th>Zona</th><th>Hora del dispositivo</th><th>Resultado</th></tr></thead><tbody>${state.v2.readings.slice(0,100).map(r=>`<tr><td>${esc(r.eventId)}<small>${esc(r.readerId)}</small></td><td>${esc(r.epc)}<small>${esc(r.unit||'Etiqueta sin vincular')}</small></td><td>${esc(r.zoneId)}</td><td>${esc(r.observedAt)}</td><td>${badge(r.unit?'Identificada':'Revisión')}</td></tr>`).join('')}</tbody></table></div></section>`}
function connectionForm(id){const c=state.v2.connections.find(c=>c.id===id);modal('Configurar conector',`<form id="v2-connection" data-id="${esc(id||'')}">${field('Nombre',`<input name="name" value="${esc(c?.name||'')}" required>`)}${field('Tipo','<select name="kind">'+['RFID HTTP','Báscula','TeamViewer','Cámara snapshot','Cámara vídeo','Gestor ERP','Agente IA','Visión IA'].map(t=>`<option ${c?.kind===t?'selected':''}>${t}</option>`).join('')+'</select>')}${field('URL HTTPS · sin contraseñas ni tokens',`<input name="url" type="url" value="${esc(c?.url||'')}" required placeholder="https://…">`)}${field('Identificador del equipo / centro',`<input name="device" value="${esc(c?.device||'')}">`)}<div class="notice">Las URL de TeamViewer abren una sesión externa; no suministran imágenes al algoritmo. La pasarela de cámara necesita vídeo compatible con el navegador o snapshots con CORS. IA y RFID entrante requieren configurar el servicio y sus secretos en servidor.</div><p id="v2-error" class="formerror"></p><button class="primary">Guardar configuración</button></form>`)}
function evidenceView(){const ev=[...state.photos.map(p=>({url:p.data,type:'image/jpeg',unit:p.unit,note:p.note,time:p.date})),...state.v2.operations.filter(o=>o.media).map(o=>({...o.media,unit:o.unit,note:o.type+' · '+ler(o.code).name,time:o.time})),...state.v2.threads.filter(m=>m.media).map(m=>({...m.media,unit:m.unit,note:m.text,time:m.time})),...state.v2.reviews.filter(r=>r.media).map(r=>({...r.media,unit:r.unit,note:'Revisión visual · '+r.method,time:r.time,analysisFile:r.analysisFile,sourceVideo:r.sourceVideo}))];return page('Archivo de evidencias','Fotos, vídeos y análisis vinculados a su operación.',vbtn('Nueva captura','deposit','primary'))+`<div class="evidence-grid">${ev.map(e=>`<article class="panel">${e.type?.startsWith('video')?`<video src="${esc(e.url)}" controls preload="metadata"></video>`:`<img src="${esc(e.url)}" alt="Evidencia ${esc(e.unit)}" loading="lazy">`}<div class="pad"><b>${esc(e.unit)}</b><p>${esc(e.note)}</p><small>${new Date(e.time).toLocaleString('es-ES')}</small><p class="mono small">SHA-256 ${esc(e.sha256?.slice(0,20)||'pendiente')}…</p><a href="${esc(e.url)}" target="_blank" rel="noopener">Abrir original ↗</a>${e.analysisFile?`<p><a href="${esc(e.analysisFile.url)}" target="_blank" rel="noopener">Análisis y parámetros ↗</a></p>`:''}${e.sourceVideo?`<p><a href="${esc(e.sourceVideo.url)}" target="_blank" rel="noopener">Vídeo origen del fotograma ↗</a></p>`:''}</div></article>`).join('')||'<div class="empty">Las evidencias guardadas aparecerán aquí con su huella digital y unidad.</div>'}</div>`}
vision=function(){return page('Visión, captura y revisión','Analiza una imagen, conserva la evidencia y registra la decisión.',vbtn('Configurar cámara','connection-new')+vbtn('Cámara de obra','deposit','primary'))+`<div class="grid2"><section class="panel pad"><div class="between"><h2>Laboratorio visual</h2><span class="badge">Análisis sobre píxeles reales</span></div><input id="vision-file" type="file" accept="image/jpeg,image/png,image/webp"><div class="vision-work"><canvas id="vision-canvas" width="640" height="400"></canvas><span id="vision-empty">Carga una fotografía para comenzar</span></div><div class="actions">${vbtn('Segmentar regiones por color','segment','primary')}${vbtn('Modelo de materiales','infer')}${vbtn('Guardar revisión','review-save')}</div><p class="small muted">La segmentación cromática agrupa píxeles, no identifica materiales. Asigna las clases con revisión humana o conecta un modelo entrenado. El área visible no equivale a masa o volumen.</p><div id="vision-results"></div></section><section class="panel pad"><h2>Conteo y volumetría</h2><p>Activa el conteo y toca cada objeto visible. Las marcas registran una anotación humana.</p>${vbtn('Activar / desactivar conteo','count')}<p id="count-result">0 objetos marcados</p><form id="v2-volume"><div class="detailgrid">${field('Longitud interior (m)','<input name="length" type="number" min="0.01" max="20" step="0.01" required>')}${field('Anchura interior (m)','<input name="width" type="number" min="0.01" max="5" step="0.01" required>')}${field('Altura interior (m)','<input name="height" type="number" min="0.01" max="5" step="0.01" required>')}${field('Ocupación estimada (%)','<input name="fill" type="number" min="0" max="100" required>')}</div><button>Calcular volumen geométrico</button><div id="volume-result" class="notice spaced">Requiere dimensiones medidas y estimación de ocupación. No deduce volumen 3D de una sola foto.</div></form><h3 class="spaced">Conexiones de cámara</h3>${state.v2.connections.filter(c=>/Cámara|TeamViewer/.test(c.kind)).map(c=>`<div class="source"><b>${esc(c.name)}</b><p>${esc(c.kind)}</p>${c.kind==='TeamViewer'?`<a href="${esc(c.url)}" target="_blank" rel="noopener">Abrir sesión TeamViewer ↗</a>`:vbtn('Abrir fuente','camera-source:'+c.id)}</div>`).join('')||'<p class="muted">Añade la URL de la pasarela o la sesión remota.</p>'}<h3 class="spaced">Revisiones guardadas</h3>${state.v2.reviews.slice(-8).reverse().map(r=>`<div class="source"><b>${esc(r.unit)}</b><p>${esc(r.note)}</p><small>${esc(r.method)} · ${r.count} marcas humanas</small></div>`).join('')}</section></div>`};
let visionImage=null,countEnabled=false,countPoints=[],volumeEstimate=null;
async function loadVision(blob){visionBlob=blob;if(visionURL)URL.revokeObjectURL(visionURL);visionURL=URL.createObjectURL(blob);visionImage=await createImageBitmap(blob);const c=$('#vision-canvas');c.width=640;c.height=Math.round(640*visionImage.height/visionImage.width);c.getContext('2d').drawImage(visionImage,0,0,c.width,c.height);$('#vision-empty').hidden=true;countPoints=[];visionRegions=[];volumeEstimate=null;$('#count-result').textContent='0 objetos marcados'}
function segment(){if(!visionImage)return toast('Carga una fotografía.');countPoints=[];$('#count-result').textContent='0 objetos marcados';const c=$('#vision-canvas'),x=c.getContext('2d');x.drawImage(visionImage,0,0,c.width,c.height);const im=x.getImageData(0,0,c.width,c.height),d=im.data;let centers=[[45,45,45],[120,105,85],[180,175,155],[225,225,225]],labels=new Uint8Array(d.length/4);for(let iter=0;iter<7;iter++){const sums=centers.map(()=>[0,0,0,0]);for(let p=0;p<labels.length;p++){let best=0,dist=Infinity;for(let j=0;j<4;j++){const v=(d[p*4]-centers[j][0])**2+(d[p*4+1]-centers[j][1])**2+(d[p*4+2]-centers[j][2])**2;if(v<dist){dist=v;best=j}}labels[p]=best;for(let k=0;k<3;k++)sums[best][k]+=d[p*4+k];sums[best][3]++}centers=centers.map((old,j)=>sums[j][3]?sums[j].slice(0,3).map(v=>v/sums[j][3]):old)}const palette=[[41,115,238],[45,205,166],[241,191,68],[162,111,225]],counts=[0,0,0,0];for(let p=0;p<labels.length;p++){const j=labels[p];counts[j]++;for(let k=0;k<3;k++)d[p*4+k]=d[p*4+k]*.45+palette[j][k]*.55}x.putImageData(im,0,0);visionRegions=counts.map((n,j)=>({region:j,visibleArea:n/labels.length,material:'Sin identificar',color:palette[j]}));$('#vision-results').innerHTML=visionRegions.map((r,i)=>`<div class="region-row"><i style="background:rgb(${r.color})"></i><span>Región ${i+1} · ${num(r.visibleArea*100,1)} % de píxeles</span><select data-region="${i}" aria-label="Clase de región ${i+1}"><option>Sin identificar</option>${mats.map(m=>`<option>${m[1]}</option>`).join('')}<option>Fondo / oclusión</option></select></div>`).join('')+'<div class="notice">K-means RGB · 4 grupos · asignación de material manual. Regiones discontinuas pueden contener materiales diferentes.</div>'}
async function infer(){if(!visionBlob)return toast('Carga una fotografía.');try{const media=await uploadEvidence(visionBlob);const r=await api('vision',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mediaId:media.id})});const d=await r.json();if(!d.configured)return toast('Modelo de materiales no configurado. Puedes segmentar por color y revisar manualmente.');$('#vision-results').textContent=JSON.stringify(d.result,null,2);state.v2.reviews.push({id:uid('AI'),media,unit:'Sin vincular',time:new Date().toISOString(),method:'Modelo externo · '+d.result.modelVersion,note:'Inferencia pendiente de validación humana',count:0,result:d.result});persist()}catch(e){toast(e.message)}}
function reviewSave(){if(!visionBlob)return toast('Carga una fotografía primero.');modal('Guardar revisión visual',`<form id="v2-review">${field('Unidad',`<select name="unit">${optsLots()}</select>`)}${field('Resultado','<select name="decision"><option>Pendiente de caracterización</option><option>Compatible según revisión humana</option><option>Impropios detectados</option><option>Imagen insuficiente</option></select>')}${field('Observación','<textarea name="note" required maxlength="1200"></textarea>')}<div class="notice">${countPoints.length} marcas humanas · ${visionRegions.length} regiones cromáticas. Se conserva el original.</div><p id="v2-error" class="formerror"></p><button class="primary">Guardar evidencia y revisión</button></form>`)}
async function cameraSource(id){const c=state.v2.connections.find(c=>c.id===id);if(!c)return;if(c.kind==='Cámara snapshot'){try{const r=await fetch(c.url,{credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)throw Error();await loadVision(await r.blob())}catch{toast('No se pudo leer el snapshot. La pasarela debe admitir HTTPS y CORS.')}}else modal('Cámara remota · '+c.name,`<video id="remote-video" src="${esc(c.url)}" crossorigin="anonymous" controls playsinline style="width:100%"></video><p>URL de vídeo compatible con el navegador. Para RTSP necesitas una pasarela WebRTC/HLS; no se abre RTSP directamente.</p>${vbtn('Capturar fotograma para análisis','remote-frame')}`)}
async function remoteFrame(){const v=$('#remote-video');if(!v?.videoWidth)return toast('La fuente aún no entrega vídeo compatible.');try{const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);const b=await new Promise(r=>c.toBlob(r,'image/jpeg',.9));closeModal();render();await loadVision(b)}catch{toast('La fuente impide capturar fotogramas. Revisa CORS en la pasarela.')}}
function audit(){let n=0;for(const l of state.lots){const reasons=[];if(l.status==='Cerrado'&&(!l.proof||!l.di))reasons.push('Cierre sin evidencia completa');if(l.recycled>l.kg)reasons.push('Reciclado superior a masa recibida');if(l.process==='Recibido'&&!l.di)reasons.push('Recepción sin DI');if(ler(l.code).hazard&&!['Bloqueado','Cuarentena','Cerrado'].includes(l.status))reasons.push('Peligroso fuera de revisión');for(const reason of reasons)if(!state.v2.alerts.some(a=>a.unit===l.id&&a.title===reason&&a.status!=='Resuelta')){raise(l.id,reason,'Revisión automática de coherencia entre campos. Comprueba la documentación original.');n++}}persist();toast(n+' nuevas incidencias de coherencia');render()}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-v2]');if(!b)return;const action=b.dataset.v2,[a,...parts]=action.split(':'),id=parts.join(':');try{switch(a){case'nav':go(id);break;case'unit':unitDetail(id);break;case'retry':initRemote();break;case'deposit':deposit(id);break;case'mat':selectedMat=id;$('#deposit-code').value=id;$('#mat-picker').innerHTML=matCards();compatibility();break;case'camera':openCamera();break;case'snapshot':snapshot();break;case'record':recordVideo();break;case'handoff':handoff(id);break;case'agent':agentOpen();break;case'ask':ask(id);break;case'audit':audit();break;case'node-new':nodeForm();break;case'node-edit':nodeForm(id);break;case'node-delete':state.v2.nodes=state.v2.nodes.filter(n=>n.id!==id);state.v2.edges=state.v2.edges.filter(e=>e.from!==id&&e.to!==id);persist();closeModal();render();break;case'node-open':{const n=state.v2.nodes.find(n=>n.id===id);if(n.type==='Unidad')unitDetail(n.ref);else if(n.type==='Tarea')taskDetail(n.ref);else if(n.type==='Gestor')go('planta');else nodeForm(id);break}case'node-link':if(!nodeConnect){nodeConnect=id;toast('Selecciona Enlazar en el nodo de destino.')}else if(nodeConnect!==id){const from=nodeConnect;nodeConnect=null;modal('Nueva relación',`<form id="v2-edge" data-from="${from}" data-to="${id}">${field('Relación','<input name="label" required maxlength="60" placeholder="genera, recibe, depende de…">')}<button class="primary spaced">Crear conexión</button></form>`)}render();break;case'edge-delete':state.v2.edges=state.v2.edges.filter(e=>e.id!==id);persist();render();break;case'zoom-in':boardZoom=Math.min(1.5,boardZoom+.1);render();break;case'zoom-out':boardZoom=Math.max(.5,boardZoom-.1);render();break;case'map-export':download('CUEVA_Relaciones.json',JSON.stringify({nodes:state.v2.nodes,edges:state.v2.edges},null,2),'application/json');break;case'task':taskDetail(id);break;case'task-search':modal('Buscar tareas',`<input id="task-q" placeholder="Título, responsable o unidad" aria-label="Buscar tareas"><div id="task-results">${state.tasks.map(t=>vbtn(t.title+' · '+t.owner,'task:'+t.id,'task-result')).join('')}</div>`);break;case'channel':channel=id;render();break;case'chat':selectedUnit=id;closeModal();go('equipo');break;case'ack':{const m=state.v2.threads.find(m=>m.id===id);m.ack=new Date().toISOString();log(m.unit,'Confirmación de lectura','Aviso '+m.id,'Conector obra');render();break}case'message-task':{const m=state.v2.threads.find(m=>m.id===id);if(m.taskId)return taskDetail(m.taskId);const t={id:uid('T'),title:m.text.slice(0,120),description:m.text,owner:'Waste manager',unit:m.unit,due:new Date().toISOString().slice(0,10),stage:'Por hacer',priority:'Media',comments:[]};state.tasks.push(t);m.taskId=t.id;persist();taskDetail(t.id);break}case'resolve':modal('Resolver incidencia',`<form id="v2-resolve" data-id="${id}">${field('Corrección realizada / evidencia','<textarea name="note" required minlength="10"></textarea>')}<button class="primary spaced">Registrar resolución</button></form>`);break;case'connection-new':connectionForm();break;case'connection-edit':connectionForm(id);break;case'pull-readings':{const r=await api('readings');const events=await r.json();for(const ev of events)acceptReading(ev);persist();render();break}case'contract':modal('Contrato de integración · CUEVA',`<p>RFID: POST /api/integrations/rfid/events · Authorization: Bearer (secreto configurado en servidor).</p><pre>${esc(JSON.stringify({eventId:'reader:sequence',readerId:'URA4-01',epc:'TAG',observedAt:'2026-09-12T10:00:00Z',siteId:'PRAT',zoneId:'Salida',antenna:1,rssiDbm:-45},null,2))}</pre><p>Respuesta: accepted / duplicate. La etiqueta se resuelve a recipiente, y el recipiente conserva su lote. Una lectura no acredita el material ni el peso.</p><p>Modelo visual: POST servidor configurado, recibe imagen original; devuelve modelVersion, classes, confidence, visibleAreaFraction y requiresReview.</p><a href="/api/contract" target="_blank">Descargar contrato JSON ↗</a>`);break;case'plant-export':download('CUEVA_Entradas_Gestor.csv',csv([['Unidad','Lote','Obra','LER','kg','Método','Proceso','Gestor','DI'],...state.lots.map(l=>[l.id,l.lotId,l.work,l.code,l.kg,l.method,l.process,l.manager,l.di])]),'text/csv');break;case'segment':segment();break;case'infer':await infer();break;case'count':countEnabled=!countEnabled;toast(countEnabled?'Toca cada objeto visible para marcarlo.':'Conteo desactivado.');break;case'review-save':reviewSave();break;case'camera-source':await cameraSource(id);break;case'remote-frame':await remoteFrame();break}}catch(error){toast(error.message)}});
function acceptReading(ev){if(!ev||typeof ev.eventId!=='string'||typeof ev.readerId!=='string'||typeof ev.epc!=='string'||!Number.isFinite(Date.parse(ev.observedAt)))throw Error('Evento inválido: eventId, readerId, epc y fecha ISO obligatorios.');if(state.v2.readings.some(r=>r.eventId===ev.eventId&&r.readerId===ev.readerId))return false;const unit=state.v2.tags[ev.epc]||null;state.v2.readings.unshift({...ev,unit,receivedAt:new Date().toISOString()});if(unit){const l=state.lots.find(l=>l.id===unit);l.lastSeen={time:ev.observedAt,zone:ev.zoneId,reader:ev.readerId};log(unit,'Lectura RFID',ev.readerId+' · '+ev.zoneId,'Pasarela / evento aportado')}return true}
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id.startsWith('v2-'))return;e.preventDefault();const d=Object.fromEntries(new FormData(f)),button=f.querySelector('button[type="submit"],button:not([type])');if(button)button.disabled=true;const error=t=>{const el=f.querySelector('#v2-error');if(el)el.textContent=t;else toast(t)};try{switch(f.id){case'v2-deposit':{const l=state.lots.find(l=>l.id===d.unit),amount=+d.amount;if(!Number.isFinite(amount)||amount<=0||amount>100000)throw Error('Cantidad inválida.');if(['Cerrado','Recibido'].includes(l.status)||['Recogido','En clasificación','Tratado','Rechazado'].includes(l.process))throw Error('La unidad ya no admite operaciones de obra.');const incompatible=l.code!==d.code||['Con impropios','Composición desconocida','Sospecha de contaminación'].includes(d.condition)||ler(d.code).hazard;if(incompatible&&!d.already)throw Error('Operación incompatible o pendiente de caracterización: no realizar. Si ya ocurrió, marca la casilla para dejar constancia.');const remove=d.type==='Retirada manual de contenido',weighed=d.measure.startsWith('kg');if(remove&&weighed&&amount>l.kg)throw Error('No puedes retirar más masa que la registrada.');const blob=captureBlob||$('#capture-file').files[0],media=await uploadEvidence(blob);const o={id:uid('OP'),unit:l.id,lotId:l.lotId,code:d.code,type:d.type,condition:d.condition,amount,measure:d.measure,actor:d.actor,note:d.note,media,time:new Date().toISOString(),status:incompatible?'Incidencia · revisar':'Pendiente de revisión visual'};state.v2.operations.unshift(o);if(d.type!=='Clasificación manual'&&weighed)l.kg+=remove?-amount:amount;if(incompatible){l.status='Revisión';raise(l.id,'Operación de contenido incompatible',`${d.type}: ${ler(d.code).name}, ${d.condition}. ${d.note}`)}log(l.id,d.type,`${amount} ${d.measure} · LER ${d.code} · ${d.condition} · ${o.status}`,'Captura manual',d.actor);stopCapture();closeModal();render();unitDetail(l.id);toast('Operación y evidencia registradas.');break}case'v2-handoff':{if(typeof validateScaleForHandoff==='function')validateScaleForHandoff(d);const l=state.lots.find(l=>l.id===d.unit);if(d.scan.trim()!==l.id&&state.v2.tags[d.scan.trim()]!==l.id)throw Error('La identificación leída no corresponde a esta unidad.');if(ler(l.code).hazard||['Bloqueado','Cuarentena'].includes(l.status))throw Error('Unidad bloqueada: requiere circuito técnico específico.');const allowed={Recogida:['En obra'],Recepción:['Recogido'],Clasificación:['Recibido'],Rechazo:['Recogido','Recibido','En clasificación']};if(!allowed[d.step].includes(l.process))throw Error('Secuencia incorrecta: estado actual '+l.process);let net=null;if(d.gross!==''){net=+d.gross-+d.tare;if(!Number.isFinite(net)||net<=0||+d.tare<0)throw Error('Bruto y tara deben producir un peso neto positivo.');if(!d.ticket.trim())throw Error('Añade referencia del ticket de pesaje.')}if(d.step==='Recepción'&&net===null&&!l.originWeight)throw Error('La recepción necesita pesaje en planta o pesaje de obra documentado.');if(['Recogida','Recepción'].includes(d.step)&&!d.di.trim())throw Error('Añade referencia del DI antes del movimiento.');const old=l.kg;if(d.step==='Recogida'&&net!==null)l.originWeight={kg:net,ticket:d.ticket,provenance:d.weightProvenance||null};if(d.step==='Recepción'){l.kg=net??l.originWeight.kg;l.method=(net!==null?'Pesaje '+(d.weightOrigin||'destino'):'Pesaje obra documentado')+((d.weightProvenance?.demo||(net===null&&l.originWeight?.provenance?.demo))?' · DEMO':'');l.status='Recibido';l.fill=0;l.zone=d.zone||'Planta del gestor';if(Math.abs(l.kg-old)>Math.max(10,old*.05))raise(l.id,'Diferencia de pesaje',`Origen registrado ${old} kg; recepción ${l.kg} kg. Conciliar el ticket y el contenido.`)}l.process=({Recogida:'Recogido',Recepción:'Recibido',Clasificación:'En clasificación',Rechazo:'Rechazado'})[d.step];if(d.step==='Rechazo'){l.status='Revisión';raise(l.id,'Rechazo en destino',d.note)}l.manager=d.manager;l.di=d.di||l.di;state.v2.receipts.unshift({id:uid('MOV'),...d,net,time:new Date().toISOString()});log(l.id,d.step,`${d.manager} · ${net===null?'Sin nuevo pesaje':net+' kg netos'} · ${d.weightOrigin||'Entrada manual'} · ${d.note}`,'Gestor / cadena de custodia',d.actor);closeModal();go('planta');render();break}case'v2-node':{const existing=state.v2.nodes.find(n=>n.id===f.dataset.id);const n={id:existing?.id||uid('NODE'),type:d.type,ref:d.ref,label:d.label,x:Math.min(1150,Math.max(0,+d.x)),y:Math.min(650,Math.max(0,+d.y))};if(existing)Object.assign(existing,n);else state.v2.nodes.push(n);persist();closeModal();render();break}case'v2-edge':state.v2.edges.push({id:uid('EDGE'),from:f.dataset.from,to:f.dataset.to,label:d.label});persist();closeModal();render();break;case'v2-task':{const t=state.tasks.find(t=>t.id===f.dataset.id);Object.assign(t,{title:d.title,owner:d.owner,due:d.due,priority:d.priority,stage:d.stage,description:d.description,tags:d.tags,checklist:d.checklist.split('\n').filter(x=>x.trim()).map(x=>({done:x.startsWith('[x]'),text:x.replace(/^\[[x ]\]\s*/, '')}))});t.comments??=[];if(d.comment.trim())t.comments.push({text:d.comment,time:new Date().toISOString()});log(t.unit,'Tarea actualizada',t.title+' · '+t.stage);closeModal();render();break}case'v2-chat':{const file=f.elements.attachment.files[0],media=file?await uploadEvidence(file):null;state.v2.threads.push({id:uid('MSG'),channel,actor:d.actor,text:d.text,unit:d.unit,media,time:new Date().toISOString(),ack:null});log(d.unit,'Conversación',d.text,'Canal '+channel,d.actor);render();break}case'v2-agent':await ask(d.question);break;case'v2-resolve':{const a=state.v2.alerts.find(a=>a.id===f.dataset.id);a.status='Resuelta';a.resolution=d.note;a.resolvedAt=new Date().toISOString();const lot=state.lots.find(l=>l.id===a.unit);if(lot?.status==='Revisión'&&lot.process==='En obra'&&!ler(lot.code).hazard&&!state.v2.alerts.some(x=>x.unit===a.unit&&x.status!=='Resuelta'))lot.status='Acopio';state.tasks.filter(t=>t.alertId===a.id).forEach(t=>t.stage='Hecho');log(a.unit,'Incidencia resuelta',a.title+': '+d.note);closeModal();render();break}case'v2-tag':{if(state.v2.tags[d.epc]&&state.v2.tags[d.epc]!==d.unit)throw Error('Etiqueta ya vinculada a otra unidad. Revisa la asignación antes de reutilizarla.');state.v2.tags[d.epc]=d.unit;log(d.unit,'Etiqueta vinculada',d.epc,'RFID / NFC');render();break}case'v2-reading':{const accepted=acceptReading(JSON.parse(d.payload));persist();toast(accepted?'Lectura registrada.':'Duplicado: no se ha registrado otra vez.');render();break}case'v2-connection':{const u=new URL(d.url);if(u.protocol!=='https:'||u.username||u.password||u.search.match(/token|key|password/i))throw Error('Usa HTTPS y no incluyas credenciales en la URL.');if(d.kind==='TeamViewer'&&!/(^|\.)teamviewer\.com$/.test(u.hostname))throw Error('La sesión debe usar un dominio oficial teamviewer.com.');const c={id:f.dataset.id||uid('CON'),...d};const i=state.v2.connections.findIndex(x=>x.id===c.id);if(i>=0)state.v2.connections[i]=c;else state.v2.connections.push(c);persist();closeModal();render();break}case'v2-volume':{volumeEstimate={length:+d.length,width:+d.width,height:+d.height,fill:+d.fill};const v=+d.length*+d.width*+d.height*(+d.fill/100);$('#volume-result').textContent=num(v,3)+' m³ estimados · geometría rectangular y ocupación declarada';break}case'v2-review':{const media=await uploadEvidence(visionBlob);state.v2.reviews.push({id:uid('REV'),unit:d.unit,media,decision:d.decision,note:d.note,regions:visionRegions,count:countPoints.length,points:countPoints,volume:volumeEstimate,method:'K-means RGB / revisión humana',time:new Date().toISOString()});if(d.decision==='Impropios detectados')raise(d.unit,'Impropios en revisión visual',d.note);log(d.unit,'Revisión visual',d.decision+' · '+d.note,'Imagen original + anotaciones');closeModal();render();break}}}catch(err){error(err.message)}finally{if(button)button.disabled=false}});
document.addEventListener('change',async e=>{try{if(['deposit-code','deposit-unit'].includes(e.target.id))compatibility();if(e.target.id==='capture-file'){captureBlob=null;$('#capture-status').textContent=e.target.files[0]?.name||'Sin archivo'}if(e.target.id==='vision-file'&&e.target.files[0])await loadVision(e.target.files[0]);if(e.target.dataset.region!==undefined)visionRegions[+e.target.dataset.region].material=e.target.value;if(e.target.id==='plant-work'){filters.plantWork=e.target.value;render()}if(e.target.id==='plant-status'){filters.plantStatus=e.target.value;render()}}catch(e){toast('No se pudo leer la imagen.')}});
document.addEventListener('input',e=>{if(e.target.id==='task-q')$('#task-results').innerHTML=state.tasks.filter(t=>fold(t.title+' '+t.owner+' '+t.unit).includes(fold(e.target.value))).map(t=>vbtn(t.title+' · '+t.owner,'task:'+t.id,'task-result')).join('')});
let dragging=null;
document.addEventListener('pointerdown',e=>{const grip=e.target.closest('.node-grip');if(!grip)return;const el=grip.closest('[data-node]'),n=state.v2.nodes.find(n=>n.id===el.dataset.node);dragging={n,el,x:e.clientX,y:e.clientY,ox:n.x,oy:n.y};grip.setPointerCapture(e.pointerId)});
document.addEventListener('pointermove',e=>{if(!dragging)return;const d=dragging;d.n.x=Math.min(1150,Math.max(0,d.ox+(e.clientX-d.x)/boardZoom));d.n.y=Math.min(650,Math.max(0,d.oy+(e.clientY-d.y)/boardZoom));d.el.style.left=d.n.x+'px';d.el.style.top=d.n.y+'px'});
document.addEventListener('pointerup',()=>{if(dragging){dragging=null;persist();render()}});
document.addEventListener('click',e=>{if(e.target.id==='vision-canvas'&&countEnabled&&visionImage){const c=e.target,r=c.getBoundingClientRect(),x=(e.clientX-r.left)*c.width/r.width,y=(e.clientY-r.top)*c.height/r.height;countPoints.push({x,y});const ctx=c.getContext('2d');ctx.fillStyle='#53efbb';ctx.beginPath();ctx.arc(x,y,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#102033';ctx.font='bold 12px sans-serif';ctx.fillText(countPoints.length,x-4,y+4);$('#count-result').textContent=countPoints.length+' objetos marcados por el revisor'}});
