render();initRemote();
connectors=function(){closeModal();go('conectores')};
about=function(){modal('CUEVA Waste Manager · evolución operativa',`<p>Organización, obra y planta del gestor en un espacio privado con registros y evidencias persistentes.</p><div class="notice">Los datos iniciales y perfiles son de demostración. Las nuevas operaciones se guardan en servidor. Los conectores externos necesitan el equipo, proveedor y configuración correspondientes. No hay cuentas separadas por rol.</div><div class="actions">${vbtn('Conectores','nav:conectores')}${btn('Exportar registros','export-json','','download')}</div>`)};
function worksView(){return page('Obras y zonas','Asigna unidades a su obra y registra coordenadas de referencia.',vbtn('Nueva obra','work-new','primary'))+`<div class="grid3">${works.map(w=>`<section class="panel pad"><span class="eyebrow">${esc(w.id)}</span><h2>${esc(w.name)}</h2><p>${state.lots.filter(l=>l.work===w.id).length} unidades · ${kg(state.lots.filter(l=>l.work===w.id).reduce((a,l)=>a+l.kg,0))}</p><small>${w.lat}, ${w.lng}</small><div class="actions spaced">${vbtn('Asignar unidades','work-assign:'+w.id)}${vbtn('Editar','work-edit:'+w.id)}</div></section>`).join('')}</div><section class="panel pad"><h2>Mapa del circuito</h2><p>La obra identifica el origen. El recipiente conserva su identidad y el lote identifica el contenido. El gestor registra recepción, clasificación y tratamiento.</p>${vbtn('Abrir relaciones','nav:mapa')}</section>`}
function workForm(id){const w=works.find(w=>w.id===id);modal('Obra / ubicación',`<form id="v2-work" data-id="${esc(w?.id||'')}">${field('Código',`<input name="id" value="${esc(w?.id||'')}" required pattern="[A-Za-z0-9-]{2,30}" ${w?'readonly':''}>`)}${field('Nombre',`<input name="name" required value="${esc(w?.name||'')}">`)}<div class="detailgrid">${field('Latitud WGS84',`<input name="lat" type="number" step="any" min="-90" max="90" value="${w?.lat||''}" required>`)}${field('Longitud WGS84',`<input name="lng" type="number" step="any" min="-180" max="180" value="${w?.lng||''}" required>`)}</div><button class="primary">Guardar obra</button></form>`)}
document.addEventListener('click',e=>{const a=e.target.closest('[data-v2]')?.dataset.v2||'';if(a==='work-new')workForm();if(a.startsWith('work-edit:'))workForm(a.slice(10));if(a.startsWith('work-assign:')){const id=a.slice(12);modal('Asignar unidad a obra',`<form id="v2-assign" data-id="${esc(id)}">${field('Unidad',`<select name="unit">${optsLots()}</select>`)}${field('Zona de obra','<input name="zone" required placeholder="Planta 2 / punto de segregación">')}<button class="primary">Guardar asignación</button></form>`)}});
document.addEventListener('submit',e=>{const f=e.target;if(!['v2-work','v2-assign'].includes(f.id))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));if(f.id==='v2-work'){const w=works.find(w=>w.id===d.id);if(w&&!f.dataset.id)return toast('Ya existe una obra con ese código.');if(w)Object.assign(w,{name:d.name,lat:+d.lat,lng:+d.lng});else works.push({id:d.id,name:d.name,lat:+d.lat,lng:+d.lng});state.v2.works=works;persist()}else{const l=state.lots.find(l=>l.id===d.unit);l.work=f.dataset.id;l.zone=d.zone;log(l.id,'Asignación de obra',l.work+' · '+l.zone)}closeModal();render()});
function fractionForm(id){const l=state.lots.find(l=>l.id===id);modal('Clasificación · salidas del lote '+l.lotId,`<form id="v2-fractions" data-id="${esc(id)}"><div class="notice">Masa recibida ${kg(l.kg)}. Registra las fracciones de salida; la suma debe coincidir con la entrada. Estas salidas no se vuelven a sumar como residuos generados.</div>${[0,1,2].map((_,i)=>`<div class="detailgrid">${field('Fracción '+(i+1),`<select name="code${i}"><option value="">Sin fracción</option>${LER.map(m=>`<option value="${m.code}">${code(m.code)} · ${m.name}</option>`).join('')}</select>`)}${field('Masa (kg)',`<input name="kg${i}" type="number" min="0" step="0.01" value="0">`)}</div>`).join('')}${field('Destino / proceso y observación','<textarea name="note" required></textarea>')}<p id="fraction-error" class="formerror"></p><button class="primary">Guardar balance de clasificación</button></form>`)}
const basePlant=plant;
plant=function(){return basePlant()+`<section class="panel pad"><h2>Clasificación y fracciones de salida</h2>${state.lots.filter(l=>l.process==='En clasificación').map(l=>`<div class="between source"><b>${l.id} · ${kg(l.kg)}</b>${vbtn('Registrar fracciones','fractions:'+l.id)}</div>`).join('')||'<p class="muted">Las unidades que pasan a clasificación aparecerán aquí.</p>'}${(state.v2.outputs||[]).map(o=>`<div class="source"><b>${esc(o.id)} · origen ${esc(o.parent)}</b><p>${cb(o.code)} ${esc(ler(o.code).name)} · ${kg(o.kg)}</p><small>${esc(o.note)} · tratamiento final pendiente</small></div>`).join('')}</section>`};
document.addEventListener('click',e=>{const a=e.target.closest('[data-v2]')?.dataset.v2||'';if(a.startsWith('fractions:'))fractionForm(a.slice(10))});
document.addEventListener('submit',e=>{const f=e.target;if(f.id!=='v2-fractions')return;e.preventDefault();const d=Object.fromEntries(new FormData(f)),l=state.lots.find(l=>l.id===f.dataset.id),fractions=[0,1,2].filter(i=>d['code'+i]).map(i=>({code:d['code'+i],kg:+d['kg'+i]}));if(!fractions.length||fractions.some(o=>!Number.isFinite(o.kg)||o.kg<=0)||Math.abs(fractions.reduce((a,o)=>a+o.kg,0)-l.kg)>.01){$('#fraction-error').textContent='Las fracciones positivas deben sumar exactamente '+kg(l.kg);return}state.v2.outputs??=[];if(state.v2.outputs.some(o=>o.parent===l.id&&o.parentLot===l.lotId)){ $('#fraction-error').textContent='Este lote ya tiene un balance de salidas. Registra una corrección en el histórico antes de modificarlo.';return}state.v2.outputs.push(...fractions.map(o=>({...o,id:uid('OUT'),parent:l.id,parentLot:l.lotId,note:d.note,time:new Date().toISOString()})));log(l.id,'Clasificación de salidas',fractions.map(o=>o.code+': '+o.kg+' kg').join(' / '),'Gestor');closeModal();render()});
$('#about').onclick=about;
